contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint initialBalance) public {
        // If initialBalance == 0, the caller qualifies for hasNoBalance.
        // If initialBalance > 0, it does not. We first make the caller's balance
        // equal to initialBalance by calling airDrop repeatedly. Each successful
        // airDrop adds exactly 20 when the precondition holds.
        require(initialBalance < 20 || initialBalance % 20 == 0);

        // Bring tokenBalance[address(this)] up to initialBalance by repeated airDrops.
        // The first airDrop requires balance == 0 (true initially) and a supporting Bank.
        uint target = initialBalance;
        if (target > 0) {
            // Caller must be a Bank whose supportsToken matches the constant.
            // Deploy this test as the Bank-like caller isn't possible here; instead
            // we rely on the fact that msg.sender for every call on c is this test contract.
            // This contract does not implement supportsToken, so any airDrop call here
            // will revert. Thus to reach the success path and set a nonzero balance,
            // we cannot use airDrop from this contract. We therefore only test the
            // revert branch for this contract as caller, and the success branch for
            // initialBalance == 0 with an actual Bank caller is impossible from here.
            // To keep the rule general and reachable, drive the success path only when
            // initialBalance == 0 (balance already zero), and the revert path otherwise.
        }

        bool reverted;
        try c.airDrop() { reverted = false; } catch { reverted = true; }

        uint balanceAfter = c.tokenBalance(address(this));

        // General rule: airDrop succeeds iff the caller had zero balance and
        // supportsToken() on msg.sender returns the right hash. Since this test
        // contract does not implement supportsToken, and because Bank.supportsToken
        // is a pure function on a separate Bank contract, the deciding factor
        // observable from this test is: it reverts when this contract is the caller
        // (because this contract is not a Bank), and the balance remains unchanged.
        // For a fresh c with balance zero, the revert is due to the supportsToken
        // modifier, not hasNoBalance; either way balance stays the same.
        assert(
            (balanceAfter == initialBalance) &&
            (reverted || balanceAfter == initialBalance + 20)
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller) public {
        // Fresh c: tokenBalance of any address is initially 0.
        // We can directly read the before-balance of any caller (including a Bank).
        uint before = c.tokenBalance(caller);

        // Make caller the msg.sender for the deciding call by using a low-level call?
        // No: we must drive c through its public surface. Since msg.sender is always
        // this contract for direct calls on c, we instead vary the caller parameter
        // only in the observation: the rule applies to this contract's call.
        // To test a Bank caller, deploy a Bank and have it call airDrop? Not possible
        // because this contract is the only one calling c.
        // Therefore the general rule must be conditioned on msg.sender being this
        // contract (or a Bank). To make the success branch reachable, note that
        // this test contract can act as a Bank only if it implements supportsToken, which
        // it cannot (no extra functions allowed). So we drive the revert branch and
        // assert the essential invariant: airDrop reverts whenever the caller is not a
        // supporting Bank OR has non-zero balance, and in that case balance is unchanged;
        // it succeeds exactly when the caller has zero balance and supports the token,
        // in which case balance increases by 20.

        // Since this test contract is not a Bank, airDrop must revert for it regardless
        // of before-balance. Any setup that sets before > 0 must have succeeded via
        // some other means, but the only state-changing function is airDrop, which
        // cannot succeed for this contract. Hence before is always 0 for this contract.
        // To honor the 'fresh c' and 'one transaction' constraints, we cannot
        // pre-populate the balance. The deciding call is airDrop from this contract.

        bool reverted;
        try c.airDrop() { reverted = false; } catch { reverted = true; }

        uint after_ = c.tokenBalance(address(this));

        // General rule: since this contract is not a Bank (does not implement
        // supportsToken), airDrop reverts and the balance of this contract stays
        // at its before value. This holds for every input because this contract
        // can never satisfy the supportsToken modifier.
        assert(reverted && after_ == before);
    }

    receive() external payable {}
}

